def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = {}
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive[oid] = opp

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    units = int(supply / WATER_REQ)
    if units < 0:
        units = 0
    competitor_count = 1 + len(alive)
    scarcity = units < competitor_count

    bob_prev_bid = None
    highest_prev = 0.0
    urgent_opp = False
    rich_threat = 0.0

    for oid, opp in alive.items():
        if opp.get('budget', 0) > rich_threat:
            rich_threat = opp.get('budget', 0)
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp = True
        prev = opp.get('previous_trace', {})
        if prev:
            pbid = prev.get('bid')
            if pbid is not None:
                if pbid > highest_prev:
                    highest_prev = pbid
                if oid == 'Bob':
                    bob_prev_bid = pbid

    pressure = highest_prev
    if bob_prev_bid is not None and bob_prev_bid > pressure:
        pressure = bob_prev_bid

    my_urgent = hp <= 3 or no_water_days >= 1
    very_urgent = hp <= 2 or no_water_days >= 2

    if very_urgent:
        target = max(pressure + 2.0, DAILY_SALARY * 0.95)
        return max(0.0, min(budget, target))

    if scarcity:
        if my_urgent:
            target = max(pressure + 2.0, DAILY_SALARY * 0.9)
        else:
            if pressure >= 110:
                target = DAILY_SALARY * 0.28
            elif pressure >= 80:
                target = DAILY_SALARY * 0.42
            else:
                target = max(DAILY_SALARY * 0.58, pressure + 1.5)
    else:
        if my_urgent:
            target = max(DAILY_SALARY * 0.72, pressure * 0.75)
        else:
            target = DAILY_SALARY * 0.18

    if day >= 8:
        if my_urgent:
            target = max(target, DAILY_SALARY * 0.88)
        else:
            target = max(target, DAILY_SALARY * 0.45)

    if rich_threat < DAILY_SALARY * 0.7 and not my_urgent:
        target = min(target, DAILY_SALARY * 0.3)

    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.15)

    desperate_for_water = my_status['hp'] <= 2
    late_game = day_context['day'] >= EPISODE_DAYS - 3

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev_bid = 0
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)

    base_bid_to_secure_water = DAILY_SALARY * 0.85 # A reasonable bid to aim for water

    if desperate_for_water:
        return min(my_status['budget'], DAILY_SALARY * 1.1 + 5) 

    if late_game:
        if my_status['hp'] < 7: 
            return min(my_status['budget'], max(base_bid_to_secure_water * 1.1, max_prev_bid + 2))
        else: 
            return min(my_status['budget'], max(base_bid_to_secure_water, max_prev_bid + 1))

    # Mid-game strategy
    if max_prev_bid > DAILY_SALARY * 0.8: 
        if my_status['hp'] > 5: 
            return min(my_status['budget'], max(base_bid_to_secure_water, max_prev_bid + 1))
        else: 
            return min(my_status['budget'], max(base_bid_to_secure_water * 1.05, max_prev_bid + 2))
    elif max_prev_bid > DAILY_SALARY * 0.5: 
        return min(my_status['budget'], max(DAILY_SALARY * 0.7, max_prev_bid + 1))
    else: # Opponents are bidding low or no bids yet
        if my_status['hp'] > 7: 
            return min(my_status['budget'], DAILY_SALARY * 0.6)
        else: 
            return min(my_status['budget'], DAILY_SALARY * 0.75)

    return min(my_status['budget'], DAILY_SALARY * 0.75) # Fallback

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # Baseline: if I'm in danger, bid to secure water.
    if hp <= 2 or no_water_days >= 2:
        target = DAILY_SALARY * 0.95
    elif hp <= 3:
        target = DAILY_SALARY * 0.75
    else:
        target = DAILY_SALARY * 0.58

    # React to yesterday trace: estimate opponents' pressure.
    prev_bids = []
    prev_hp_after = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass
        if prev.get('hp_after') is not None:
            try:
                prev_hp_after.append(float(prev.get('hp_after')))
            except Exception:
                pass

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If someone was bidding near/above strong threshold, slightly outbid.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = max(target, min(budget, DAILY_SALARY * 0.35) + 25)
        # If bids were generally low, we can bid enough to stay ahead.
        elif highest_prev_bid <= DAILY_SALARY * 0.6:
            target = max(target, DAILY_SALARY * 0.62)
        else:
            # Mid pressure: bid just above the median-ish.
            sorted_bids = sorted(prev_bids)
            mid = sorted_bids[len(sorted_bids)//2]
            target = max(target, mid + 8)

    # Supply sensitivity: lower supply increases urgency.
    if supply <= float(MIN_SUPPLY) + 0.5:
        target *= 1.15
    elif supply >= float(MAX_SUPPLY) - 0.5:
        target *= 0.95

    # Ensure affordability and keep within reasonable bounds.
    if budget <= 0:
        return 0.0

    # Never exceed budget.
    bid = min(budget, target)

    # Light floor to avoid always losing to aggressive bids.
    # If budget is very small, comply.
    min_bid = min(budget, DAILY_SALARY * 0.2)
    if bid < min_bid:
        bid = min_bid

    # Final clamp.
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        bid = avg_prev * 1.05
    else:
        bid = DAILY_SALARY * 0.6

    if my_status['hp'] < 4:
        bid = max(bid, DAILY_SALARY * 0.8)

    return float(min(my_status['budget'], bid))
